import{_ as a,o as n,c as o,ag as e}from"./chunks/framework.1IVNT0ce.js";const D=JSON.parse('{"title":"Session","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/session.md","filePath":"concepts/session.md"}'),l={name:"concepts/session.md"};function t(p,s,i,c,r,F){return n(),o("div",null,[...s[0]||(s[0]=[e(`<h1 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h1><p><code>Session</code> is the per-terminal runtime object in Klix. If <code>App</code> is the application definition, <code>Session</code> is the active instance.</p><p>See also:</p><ul><li><a href="./app">App</a></li><li><a href="./state">State</a></li><li><a href="./ui">UI Namespace</a></li><li><a href="./../guides/persistence">Persistence</a></li></ul><h2 id="why-session-exists" tabindex="-1">Why <code>Session</code> Exists <a class="header-anchor" href="#why-session-exists" aria-label="Permalink to &quot;Why \`Session\` Exists&quot;">​</a></h2><p>A framework like Klix needs a place to hold runtime state that is not global:</p><ul><li>current application state</li><li>metadata about the terminal</li><li>runtime UI handles</li><li>input history</li><li>background tasks</li></ul><p>That is what <code>Session</code> does.</p><h2 id="what-lives-on-a-session" tabindex="-1">What Lives On A Session <a class="header-anchor" href="#what-lives-on-a-session" aria-label="Permalink to &quot;What Lives On A Session&quot;">​</a></h2><p>The current implementation exposes these important attributes:</p><ul><li><code>session.id</code></li><li><code>session.state</code></li><li><code>session.metadata</code></li><li><code>session.history</code></li><li><code>session.ui</code></li><li><code>session.input_engine</code></li></ul><p><code>session.ui</code> and <code>session.input_engine</code> are attached during startup. They are <code>None</code> until the runtime has been built.</p><h2 id="typed-state" tabindex="-1">Typed State <a class="header-anchor" href="#typed-state" aria-label="Permalink to &quot;Typed State&quot;">​</a></h2><p>The most common reason to use <code>Session</code> is typed state access:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#BABED8;"> dataclasses </span><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> dataclass</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> klix</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">dataclass</span></span>
<span class="line"><span style="color:#C792EA;">class</span><span style="color:#FFCB6B;"> MyState</span><span style="color:#89DDFF;">(</span><span style="color:#FFCB6B;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">SessionState</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    logged_in</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> bool</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> False</span></span>
<span class="line"><span style="color:#BABED8;">    username</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> &quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">app </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">App</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">mytool</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> state_schema</span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;">MyState</span><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/login</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Log in</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> login</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">state</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">logged_in</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> True</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">state</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">username</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">alice</span><span style="color:#89DDFF;">&quot;</span></span></code></pre></div><p>See <a href="./../guides/working-with-state">Working with State</a>.</p><h2 id="terminal-metadata" tabindex="-1">Terminal Metadata <a class="header-anchor" href="#terminal-metadata" aria-label="Permalink to &quot;Terminal Metadata&quot;">​</a></h2><p>Klix captures a small <code>TerminalMetadata</code> object on startup. It currently contains:</p><ul><li><code>env</code></li><li><code>width</code></li><li><code>height</code></li><li><code>start_time</code></li><li><code>term_program</code></li><li><code>interactive</code></li></ul><p>Example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/env</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Show terminal metadata</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> env</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">output</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">json</span><span style="color:#89DDFF;">(</span></span>
<span class="line"><span style="color:#89DDFF;">        {</span></span>
<span class="line"><span style="color:#89DDFF;">            &quot;</span><span style="color:#C3E88D;">interactive</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#82AAFF;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">metadata</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">interactive</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">            &quot;</span><span style="color:#C3E88D;">term_program</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#82AAFF;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">metadata</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">term_program</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">            &quot;</span><span style="color:#C3E88D;">size</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span><span style="color:#82AAFF;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">metadata</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">width</span><span style="color:#89DDFF;">,</span><span style="color:#82AAFF;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">metadata</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">height</span><span style="color:#89DDFF;">],</span></span>
<span class="line"><span style="color:#89DDFF;">        }</span></span>
<span class="line"><span style="color:#89DDFF;">    )</span></span></code></pre></div><h2 id="background-tasks" tabindex="-1">Background Tasks <a class="header-anchor" href="#background-tasks" aria-label="Permalink to &quot;Background Tasks&quot;">​</a></h2><p><code>Session.create_task()</code> lets you schedule session-scoped async work:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> asyncio</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/watch</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Run a background watcher</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> def</span><span style="color:#82AAFF;"> watch</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#C792EA;">    async</span><span style="color:#C792EA;"> def</span><span style="color:#82AAFF;"> worker</span><span style="color:#89DDFF;">():</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">        for</span><span style="color:#BABED8;"> i </span><span style="color:#89DDFF;font-style:italic;">in</span><span style="color:#82AAFF;"> range</span><span style="color:#89DDFF;">(</span><span style="color:#F78C6C;">3</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">            await</span><span style="color:#BABED8;"> asyncio</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">sleep</span><span style="color:#89DDFF;">(</span><span style="color:#F78C6C;">1</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">            session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#C792EA;">f</span><span style="color:#C3E88D;">&quot;tick </span><span style="color:#F78C6C;">{</span><span style="color:#82AAFF;">i </span><span style="color:#89DDFF;">+</span><span style="color:#F78C6C;"> 1}</span><span style="color:#C3E88D;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> dim</span><span style="color:#89DDFF;">=True)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">create_task</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">worker</span><span style="color:#89DDFF;">())</span></span></code></pre></div><p>Klix tracks these tasks and waits on them during shutdown.</p><h2 id="how-it-fits-the-architecture" tabindex="-1">How It Fits The Architecture <a class="header-anchor" href="#how-it-fits-the-architecture" aria-label="Permalink to &quot;How It Fits The Architecture&quot;">​</a></h2><p>Every handler and middleware function gets a <code>Session</code> because it is the shortest path to the active runtime:</p><ul><li>state</li><li>UI</li><li>metadata</li><li>background tasks</li></ul><p>That keeps function signatures simple without forcing global variables.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><h3 id="using-session-ui-before-startup" tabindex="-1">Using <code>session.ui</code> before startup <a class="header-anchor" href="#using-session-ui-before-startup" aria-label="Permalink to &quot;Using \`session.ui\` before startup&quot;">​</a></h3><p>If you instantiate a <code>Session</code> yourself outside the normal <code>App.run()</code> path, you are responsible for attaching <code>session.ui</code> and <code>session.input_engine</code>.</p><h3 id="putting-app-definition-into-session-state" tabindex="-1">Putting app definition into session state <a class="header-anchor" href="#putting-app-definition-into-session-state" aria-label="Permalink to &quot;Putting app definition into session state&quot;">​</a></h3><p>State should hold runtime data, not command definitions, renderer objects, or application configuration that already lives on <code>App</code>.</p><h3 id="assuming-session-history-is-fully-managed-everywhere" tabindex="-1">Assuming <code>session.history</code> is fully managed everywhere <a class="header-anchor" href="#assuming-session-history-is-fully-managed-everywhere" aria-label="Permalink to &quot;Assuming \`session.history\` is fully managed everywhere&quot;">​</a></h3><p><code>session.history</code> is the live per-session command history backing the input engine.</p><p>That means:</p><ul><li>Up/Down arrow navigation reads from it</li><li>duplicate consecutive commands are skipped</li><li><code>AppConfig(max_history_size=...)</code> trims it automatically</li></ul><p>The field is still just a Python list, so if you mutate it directly, do it deliberately.</p>`,39)])])}const d=a(l,[["render",t]]);export{D as __pageData,d as default};
